class FunctionFactory(object):
    def __init__(self, account_type):
        if account_type == 'PBOX_PT_INTERFACE':
            self.stock_dict = STOCK_FUNCTION_DICT
            self.future_dict = FUTURE_FUNCTION_DICT
            self.global_dict = GLOBAL_FUNCTION_DICT
            self.algo_dict = ALGO_FUNCTION_DICT
